function openReview(record=state){reviewRecord=record;note=record.reviewNote||'';operator=record.reviewer||operator||'';renderReview();$('#review-dialog').showModal();}
function renderReview(){
 microscope?.dispose();microscope=null;
 const record=reviewRecord||state,d=deriveDemo(record,{sampleLoaded:true,inserted:true}),rs=reactions(record),r=rs.find(x=>x.id===selectedReaction)||rs[0];selectedReaction=r.id;
 const complete=record.elapsed>=600,eligible=canAuthorise(record);
 $('#review-body').innerHTML=`<div class="dialog-heading"><div><span class="step-label">${esc(record.patient.id)} / ${esc(CARTRIDGES[record.cartridge].name)}</span><h2>Test results</h2></div><button data-action="close-review" aria-label="Close results">${icon('close')}</button></div><div class="review-layout"><section><div class="review-summary">${badge(d.machine.title,d.machine.tone)}<p>${esc(d.instruction)}</p></div><div class="reaction-cards">${rs.map(x=>`<button class="reaction-card ${x.id===selectedReaction?'active':''}" data-reaction="${x.id}"><span>${esc(x.name)}</span><strong>${x.ready?(x.positive===null?'Unclear':x.positive?'Reactive':'Nonreactive'):'Awaiting readout'}</strong></button>`).join('')}</div><div class="review-evidence"><div id="review-microscope"></div><div><h3>${esc(r.name)}</h3><p>${esc(r.input)} tested with ${esc(r.reagent)}.</p><strong>${r.ready?esc(r.interpretation):'This chamber has not been read yet.'}</strong></div></div><details class="technical-details" ${d.phase==='blocked'?'open':''}><summary>Quality control findings</summary><div class="qc-list">${qcChecks(record).map(x=>`<div class="qc-item"><strong>${esc(x.name)}</strong>${badge(x.status==='pass'?'Passed':x.status==='fail'?'Action required':'Pending',x.status==='fail'?'danger':x.status==='pass'?'success':'neutral')}<p>${esc(x.detail)}</p></div>`).join('')}</div></details></section><aside class="review-actions"><h3>Laboratory review</h3><p>${eligible?'The required findings and controls are satisfactory. A qualified reviewer can authorise the record.':!complete?'Complete the test to review the full record.':'This record cannot be authorised until its unresolved findings are investigated.'}</p><label for="operator">Reviewer ID</label><input id="operator" value="${esc(operator)}" placeholder="Enter reviewer ID" maxlength="40"><label for="review-note">Observation</label><textarea id="review-note" rows="3">${esc(note)}</textarea><button class="primary-action" data-action="authorise" ${!eligible||!operator.trim()?'disabled':''}>Authorise result</button><button data-action="hold">Hold for investigation</button><button data-action="repeat" ${record!==state?'disabled title="Use an available bay to repeat a retained record"':''}>Repeat test</button><button data-action="handover" ${!record.authorised||!record.network||record.handedOver?'disabled':''}>Acknowledge ward handover</button><button class="text-button" data-action="report">Download record</button><p class="review-limits">${!record.network?'Transfer pending. The hospital connection is unavailable.':'Authorisation and ward handover are separate from physical collection and bedside checks.'}</p></aside></div>`;
 if(r.ready){microscope=new ReactionViewer($('#review-microscope'));microscope.update({reaction:r});}else $('#review-microscope').innerHTML='<div class="waiting-image">Awaiting optical readout</div>';
}
