 $('#details-body').innerHTML=`<div class="dialog-heading"><div><span class="step-label">TECHNICAL CONTROLS</span><h2>Quality controls and records</h2></div><button data-action="close-details" aria-label="Close quality controls">${icon('close')}</button></div><p>Choose a condition to inspect the system response. Resolve any failed check before starting a fresh test.</p><div class="fault-grid">${FAULTS.map(f=>`<label class="fault-toggle"><input type="checkbox" data-fault="${f.id}" ${state.faults.includes(f.id)?'checked':''}><span>${esc(f.name)}</span></label>`).join('')}<label class="fault-toggle"><input id="network-fault" type="checkbox" ${!state.network?'checked':''}><span>Disconnect hospital network</span></label></div><details class="technical-details"><summary>Event record</summary><div class="event-list">${[...state.audit].reverse().map(x=>`<p>${esc(x.event).replace(/simulated/gi,'demonstration').replace(/simulation/gi,'demonstration')}</p>`).join('')}</div></details>`;
